@page "/"
@inject Bovis.Interfaces.Configuration.IConfigurationStore configurationStore
@inject ILogger<Index> Logger
<PageTitle>BoVis Bohrsäulenvisualisierung</PageTitle>

<h1>Liste der Dienste</h1>
@foreach (var tn in services)
{
    <h3>
        @tn.Name <a href="edit_@tn.Editor?sid=new"><i class="bi bi-plus-circle"></i></a>

    </h3>
    <table class="table table-striped">
        <thead>
            <tr>
                <th scope="col">Name</th>
                <th scope="col">Beschreibung</th>
                <th scope="col">Geändert</th>
            </tr>
        </thead>
        <tbody>

            @foreach (var e in configurationStore.ListObjects("services/%"))
            {
                if (e.ContentType == tn.MimeType)
                {
                    string dn = e.DisplayName;
                    if (string.IsNullOrEmpty(dn)) dn = "(unnamed)";
                    string sid = System.IO.Path.GetFileName(e.Name); 
                    if (sid.StartsWith(".")) continue; // skip hidden services                   
                    <tr>
                        <td width="20%">
                            <a href="edit_@tn.Editor?sid=@sid">@dn</a>
                        </td>
                        <td width="60%">
                            @e.Description
                        </td>
                        <td width="20%">@e.Modified</td>
                    </tr>
                }
            }
        </tbody>
    </table>
}

@code {
    static List<Bovis.Interfaces.BovisServiceAttribute> services = Bovis.Interfaces.BovisServiceAttribute.Implementors();
}
